        pub fn claim_social_fee_pda(
            ctx: Context<ClaimSocialFeePda>,
            user_id: ZcString,
            platform: u8,
        ) -> Result<Option<SocialFeePdaClaimed>> {
            if !(ctx.accounts.social_claim_authority.address()
                == ctx.accounts.fee_program_global.social_claim_authority)
            {
                return Err((FeesError::NotAuthorized).into());
            }
            if !(ctx.accounts.fee_program_global.disable_flags & 0x02 == 0) {
                return Err((FeesError::FeatureDeactivated).into());
            }
            let now = unix_timestamp()?;
            let pda = &mut ctx.accounts.social_fee_pda;
            let elapsed = now.saturating_sub(pda.last_claimed as i64).max(0) as u64;
            if elapsed < ctx.accounts.fee_program_global.claim_rate_limit {
                {
                    let mut logger = ::naclac_core::pinocchio_log::logger::Logger::<
                        128,
                    >::default();
                    logger.append("Claim rate limit exceeded");
                    logger.log();
                };
                return Ok(None);
            }
            let data_len = 8 + core::mem::size_of::<SocialFeePda>();
            let rent_exempt_minimum = Rent::get()?.try_minimum_balance(data_len)?;
            let claimable_before = ctx
                .accounts
                .social_fee_pda
                .to_account_info()
                .lamports();
            let amount_claimed = claimable_before.saturating_sub(rent_exempt_minimum);
            let recipient_balance_before = ctx.accounts.recipient.lamports();
            if amount_claimed > 0 {
                ctx.accounts.social_fee_pda.sub_lamports(amount_claimed)?;
                ctx.accounts.recipient.add_lamports(amount_claimed)?;
            }
            let pda = &mut ctx.accounts.social_fee_pda;
            pda.total_claimed = accumulate_claimed(pda.total_claimed, amount_claimed)?;
            pda.last_claimed = now as u64;
            let lifetime_claimed = pda.total_claimed;
            let recipient_balance_after = ctx.accounts.recipient.lamports();
            let event = {
                let mut __event = <SocialFeePdaClaimed as core::default::Default>::default();
                __event.timestamp = (now).into();
                __event.user_id = (String::from(user_id.as_str())).into();
                __event.platform = (platform).into();
                __event.social_fee_pda = (ctx.accounts.social_fee_pda.address()).into();
                __event.recipient = (ctx.accounts.recipient.address()).into();
                __event.social_claim_authority = (ctx
                    .accounts
                    .social_claim_authority
                    .address())
                    .into();
                __event.amount_claimed = (amount_claimed).into();
                __event.claimable_before = (claimable_before).into();
                __event.lifetime_claimed = (lifetime_claimed).into();
                __event.recipient_balance_before = (recipient_balance_before).into();
                __event.recipient_balance_after = (recipient_balance_after).into();
                __event.quote_mint = (Address::default()).into();
                __event.emit();
                __event
            };
            Ok(Some(event))
        }
