        pub fn initialize_fee_program_global(
            ctx: Context<InitializeFeeProgramGlobal>,
            social_claim_authority: Address,
            disable_flags: u8,
            claim_rate_limit: u64,
        ) -> Result {
            if !(ctx.accounts.authority.address() == ctx.accounts.pump_global.authority)
            {
                return Err((FeesError::InvalidAdmin).into());
            }
            let timestamp = unix_timestamp()?;
            let fee_program_global = &mut ctx.accounts.fee_program_global;
            fee_program_global.authority = ctx.accounts.authority.address();
            fee_program_global.social_claim_authority = social_claim_authority;
            fee_program_global.disable_flags = disable_flags;
            fee_program_global.claim_rate_limit = claim_rate_limit;
            {
                let mut __event = <InitializeFeeProgramGlobalEvent as core::default::Default>::default();
                __event.timestamp = (timestamp).into();
                __event.claim_rate_limit = (claim_rate_limit).into();
                __event.authority = (ctx.accounts.authority.address()).into();
                __event.social_claim_authority = (social_claim_authority).into();
                __event.disable_flags = (disable_flags).into();
                __event.emit();
                __event
            };
            Ok(())
        }
