        /// Update Fee Shares, make sure to distribute all the fees before calling this.
        /// Same confirmed mechanics as `update_fee_shares_v2`, WSOL-only.
        pub fn update_fee_shares(
            ctx: Context<UpdateFeeShares>,
            bonding_curve_bump: u8,
            pump_creator_vault_bump: u8,
            coin_creator_vault_authority_bump: u8,
            shareholders: ZcVec<Shareholder>,
        ) -> Result {
            if !(ctx.accounts.authority.address() == ctx.accounts.sharing_config.admin) {
                return Err((FeesError::NotAuthorized).into());
            }
            if !(ctx.accounts.sharing_config.version != 1) {
                return Err((FeesError::InvalidSharingConfig).into());
            }
            if !(ctx.accounts.sharing_config.admin_revoked == 0) {
                return Err((FeesError::FeeSharesAlreadyUpdated).into());
            }
            let new_shareholders: Vec<Shareholder> = shareholders.iter().collect();
            validate_shareholders(&new_shareholders)?;
            let current_shareholders_len = ctx.accounts.sharing_config.shareholders_len
                as usize;
            if !(ctx.remaining_accounts.len() == current_shareholders_len) {
                return Err((FeesError::NotEnoughRemainingAccounts).into());
            }
            ctx.accounts
                .pump_amm_program
                .transfer_creator_fees_to_pump_v2(
                    TransferCreatorFeesToPumpV2CpiAccounts {
                        payer: ctx.accounts.authority.to_cpi_handle_mut(),
                        quote_mint: ctx.accounts.wsol_mint.to_cpi_handle(),
                        token_program: ctx.accounts.token_program.to_cpi_handle(),
                        system_program: ctx.accounts.system_program.to_cpi_handle(),
                        associated_token_program: ctx
                            .accounts
                            .associated_token_program
                            .to_cpi_handle(),
                        coin_creator: ctx.accounts.sharing_config.to_cpi_handle(),
                        coin_creator_vault_authority: ctx
                            .accounts
                            .coin_creator_vault_authority
                            .to_cpi_handle_mut(),
                        coin_creator_vault_ata: ctx
                            .accounts
                            .coin_creator_vault_ata
                            .to_cpi_handle_mut(),
                        pump_creator_vault: ctx
                            .accounts
                            .pump_creator_vault
                            .to_cpi_handle_mut(),
                        pump_creator_vault_ata: ctx
                            .accounts
                            .pump_creator_vault_ata
                            .to_cpi_handle_mut(),
                    },
                    coin_creator_vault_authority_bump,
                    pump_creator_vault_bump,
                )?;
            let mut remaining_for_distribute: Vec<(AccountInfo, bool, bool)> = Vec::with_capacity(
                current_shareholders_len,
            );
            for account in ctx.remaining_accounts {
                remaining_for_distribute.push((*account, true, false));
            }
            let pump_fees_authority_signer_seeds: &[&[u8]] = &[
                PUMP_FEES_AUTHORITY_SEED,
                &[ctx.bumps.pump_fees_authority],
            ];
            let pump_fees_authority_signer: &[&[&[u8]]] = &[
                pump_fees_authority_signer_seeds,
            ];
            ctx.accounts
                .pump_program
                .distribute_creator_fees_v2_with_remaining_accounts(DistributeCreatorFeesV2CpiCall {
                    accounts: DistributeCreatorFeesV2CpiAccounts {
                        payer: ctx.accounts.authority.to_cpi_handle_mut(),
                        mint: ctx.accounts.mint.to_cpi_handle(),
                        bonding_curve: ctx.accounts.bonding_curve.to_cpi_handle(),
                        sharing_config: ctx.accounts.sharing_config.to_cpi_handle(),
                        creator_vault: ctx
                            .accounts
                            .pump_creator_vault
                            .to_cpi_handle_mut(),
                        system_program: ctx.accounts.system_program.to_cpi_handle(),
                        creator_vault_quote_token_account: ctx
                            .accounts
                            .pump_creator_vault_ata
                            .to_cpi_handle_mut(),
                        quote_mint: ctx.accounts.wsol_mint.to_cpi_handle(),
                        quote_token_program: ctx.accounts.token_program.to_cpi_handle(),
                        associated_token_program: ctx
                            .accounts
                            .associated_token_program
                            .to_cpi_handle(),
                        pump_fees_authority: ctx
                            .accounts
                            .pump_fees_authority
                            .to_cpi_handle(),
                    },
                    bonding_curve_bump,
                    creator_vault_bump: pump_creator_vault_bump,
                    initialize_ata: Bool::from(false),
                    signer_seeds: pump_fees_authority_signer,
                    remaining_accounts: &remaining_for_distribute,
                })?;
            let timestamp = unix_timestamp()?;
            let sharing_config_address = ctx.accounts.sharing_config.address();
            let mint_address = ctx.accounts.mint.address();
            let admin = ctx.accounts.sharing_config.admin;
            let sharing_config = &mut ctx.accounts.sharing_config;
            for (i, shareholder) in new_shareholders.iter().enumerate() {
                sharing_config.shareholders[i] = *shareholder;
            }
            sharing_config.shareholders_len = new_shareholders.len() as u32;
            sharing_config.admin_revoked = 1;
            let version = sharing_config.version;
            {
                let mut __event = <UpdateFeeSharesEvent as core::default::Default>::default();
                __event.timestamp = (timestamp).into();
                __event.mint = (mint_address).into();
                __event.sharing_config = (sharing_config_address).into();
                __event.admin = (admin).into();
                __event.new_shareholders = (new_shareholders).into();
                __event.version = (version).into();
                __event.emit();
                __event
            };
            Ok(())
        }
