        pub fn upsert_fee_tiers(
            ctx: Context<UpsertFeeTiers>,
            fee_tiers: ZcVec<FeeTier>,
            offset: u8,
        ) -> Result {
            if !(ctx.accounts.admin.address() == ctx.accounts.fee_config.admin) {
                return Err((FeesError::InvalidAdmin).into());
            }
            let cfg = &mut ctx.accounts.fee_config;
            let offset = offset as usize;
            let current_len = cfg.fee_tiers_len as usize;
            if !(offset <= current_len) {
                return Err((FeesError::OffsetNotContinuous).into());
            }
            let new_len = core::cmp::max(current_len, offset + fee_tiers.len());
            if !(new_len <= MAX_FEE_TIERS) {
                return Err((FeesError::TooManyFeeTiers).into());
            }
            for (i, tier) in fee_tiers.iter().enumerate() {
                cfg.fee_tiers[offset + i] = tier;
            }
            cfg.fee_tiers_len = new_len as u32;
            validate_fee_tiers(&cfg.fee_tiers[..new_len])?;
            let timestamp = unix_timestamp()?;
            let fee_tiers: Vec<FeeTier> = fee_tiers.iter().collect();
            {
                let mut __event = <UpsertFeeTiersEvent as core::default::Default>::default();
                __event.timestamp = (timestamp).into();
                __event.admin = (ctx.accounts.admin.address()).into();
                __event.fee_config = (ctx.accounts.fee_config.address()).into();
                __event.fee_tiers = (fee_tiers).into();
                __event.offset = (offset as u8).into();
                __event.emit();
                __event
            };
            Ok(())
        }
